INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2785233, 385192, 61012, '<td valign="top">I''m not sure about the exposure here. Seems a bit blown out. I like the composition and the mood conveyed though</td>', 'I''m not sure about the exposure here. Seems a bit blown out. I like the composition and the mood conveyed though', '2006-09-01 19:53:12.000000', NULL, 1),
(2785239, 388657, 61012, '<td valign="top">Wow, Lighting and DOF spot on. Very nice!</td>', 'Wow, Lighting and DOF spot on. Very nice!', '2006-09-01 19:55:05.000000', NULL, 1),
(2785245, 387806, 326, '<td valign="top">WAY COOL!! Love this one! 10</td>', 'WAY COOL!! Love this one! 10', '2006-09-01 19:56:57.000000', NULL, 1),
(2785249, 388704, 7485, '<td valign="top">Fabulous concept, and I love the irony of the dour expressions in this ''field of dreams''. This image is just two details away from a 10: The cloud in the upper right corner pulls the eye away from the subjects, and the horizon going through the heads just doesn''t work for me (higher vantage point with their heads entirely below the horizon would have been best).</td>', 'Fabulous concept, and I love the irony of the dour expressions in this ''field of dreams''. This image is just two details away from a 10: The cloud in the upper right corner pulls the eye away from the subjects, and the horizon going through the heads just doesn''t work for me (higher vantage point with their heads entirely below the horizon would have been best).', '2006-09-01 19:57:19.000000', NULL, 1),
(2785250, 388842, 326, '<td valign="top">lol....</td>', 'lol....', '2006-09-01 19:57:58.000000', NULL, 1),
(2785252, 387597, 61012, '<td valign="top">Nice capture but I''m not sure about the DOF. Maybe a little too soft for the happy mood. I would have liked to see it a bit sharper.</td>', 'Nice capture but I''m not sure about the DOF. Maybe a little too soft for the happy mood. I would have liked to see it a bit sharper.', '2006-09-01 19:58:22.000000', NULL, 1),
(2785254, 388868, 56797, '<td valign="top">a bit busy with all that grass but nice colors and focus on the frog.</td>', 'a bit busy with all that grass but nice colors and focus on the frog.', '2006-09-01 19:59:33.000000', NULL, 1),
