(2786841, 388165, 62095, '<td valign="top">Interesting crop. Good reflection capture, the droplets are almost unreal.</td>', 'Interesting crop. Good reflection capture, the droplets are almost unreal.', '2006-09-02 04:35:03.000000', NULL, 1),
(2786843, 384714, 62095, '<td valign="top">For me this shot has the focal point just in front of where it should be.  My eyes go to the piece of ground to the front of the animal, rather than the animal''s face.</td>', 'For me this shot has the focal point just in front of where it should be.  My eyes go to the piece of ground to the front of the animal, rather than the animal''s face.', '2006-09-02 04:36:23.000000', NULL, 1),
