(2793427, 387468, 43774, '<td valign="top">I like the colours and the glow from the fog, very nice.</td>', 'I like the colours and the glow from the fog, very nice.', '2006-09-03 22:25:10.000000', NULL, 1),
(2793428, 386244, 43774, '<td valign="top">A very calm photo, nice glow in the sky.</td>', 'A very calm photo, nice glow in the sky.', '2006-09-03 22:25:29.000000', NULL, 1),
