INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2793474, 388857, 3306, '<td valign="top">Adorable portrait. Great job. The lighting is right on.</td>', 'Adorable portrait. Great job. The lighting is right on.', '2006-09-03 22:46:14.000000', NULL, 1),
(2793481, 388668, 10867, '<td valign="top">Great shot of Esme, but I don''t think the all the negative space over her head really contributes anything to the effectiveness of the image.  Me feeling is that the image would be stronger if you cropped about half of the negative space off.</td>', 'Great shot of Esme, but I don''t think the all the negative space over her head really contributes anything to the effectiveness of the image.  Me feeling is that the image would be stronger if you cropped about half of the negative space off.', '2006-09-03 22:47:44.000000', NULL, 1),
(2793484, 385880, 21627, '<td valign="top">Good composition and colors, but there is a lot of noise.</td>', 'Good composition and colors, but there is a lot of noise.', '2006-09-03 22:49:07.000000', NULL, 1),
(2793488, 387754, 10867, '<td valign="top">Wonderfully intimate and telling portrait!  9</td>', 'Wonderfully intimate and telling portrait!  9', '2006-09-03 22:50:14.000000', NULL, 1),
(2793493, 386997, 3306, '<td valign="top">Well done.</td>', 'Well done.', '2006-09-03 22:56:11.000000', NULL, 1),
(2793496, 387522, 42826, '<td valign="top">Technical: wonderful composition and coloring.  The lower half of the sky seems a little blown out but i don''t think it''s too bad!<br/>Creativity: it might not be the most creative image, but I do think what helps with this is the other bails in the background.  <br/>Personal Opinion: I like the image, i am mutual on the border...i don''t think it was necessary, but it does look nice!<br/>Score: 9</td>', 'Technical: wonderful composition and coloring.  The lower half of the sky seems a little blown out but i don''t think it''s too bad!Creativity: it might not be the most creative image, but I do think what helps with this is the other bails in the background.  Personal Opinion: I like the image, i am mutual on the border...i don''t think it was necessary, but it does look nice!Score: 9', '2006-09-03 22:57:07.000000', NULL, 1),
(2793515, 388599, 3306, '<td valign="top">Quite a stunning portrait. I know only 2 people on this site with this skill; Kiwiness and Librodo. If you are not either of them then you have joined their ranks. Great job.</td>', 'Quite a stunning portrait. I know only 2 people on this site with this skill; Kiwiness and Librodo. If you are not either of them then you have joined their ranks. Great job.', '2006-09-03 23:09:44.000000', NULL, 1),
(2793527, 383661, 25787, '<td valign="top">Okay shot, but the subject looks totally uninterested.</td>', 'Okay shot, but the subject looks totally uninterested.', '2006-09-03 23:14:02.000000', NULL, 1),
(2793530, 388586, 25787, '<td valign="top">Pretty good.  Left side a little soft on focus.</td>', 'Pretty good.  Left side a little soft on focus.', '2006-09-03 23:14:43.000000', NULL, 1),
(2793536, 384061, 25787, '<td valign="top">Cool tube shot.</td>', 'Cool tube shot.', '2006-09-03 23:15:22.000000', NULL, 1),
(2793538, 383360, 25787, '<td valign="top">Wow, looks 3 dimensional.</td>', 'Wow, looks 3 dimensional.', '2006-09-03 23:15:47.000000', NULL, 1),
