(2799533, 389024, 31885, '<td valign="top">Certainly interesting! I like the idea</td>', 'Certainly interesting! I like the idea', '2006-09-05 06:30:27.000000', NULL, 1),
(2799535, 377423, 25355, '<td valign="top">Terrific detail, though I wish there was just a little more space between the frame and the eye on the left.</td>', 'Terrific detail, though I wish there was just a little more space between the frame and the eye on the left.', '2006-09-05 06:30:39.000000', NULL, 1),
