(2805827, 388522, 39287, '<td valign="top">Very nice picture, I love the colors... 8</td>', 'Very nice picture, I love the colors... 8', '2006-09-06 14:54:21.000000', NULL, 1),
(2805830, 389026, 48717, '<td valign="top">Canadian Rockies?  If so, I have been there.  Great blues.  The sky could stand a little noise reduction, but otherwise very nice.</td>', 'Canadian Rockies?  If so, I have been there.  Great blues.  The sky could stand a little noise reduction, but otherwise very nice.', '2006-09-06 14:56:23.000000', NULL, 1),
