(2805853, 387070, 41794, '<td valign="top">Like the capture and the high key PP, but would have liked it better if you could see the head of the bird more.</td>', 'Like the capture and the high key PP, but would have liked it better if you could see the head of the bird more.', '2006-09-06 15:04:21.000000', NULL, 1),
(2805855, 388653, 44611, '<td valign="top">Fabulous sunset well captured.</td>', 'Fabulous sunset well captured.', '2006-09-06 15:04:50.000000', NULL, 1),
(2805860, 388310, 41794, '<td valign="top">What a cute little bugger! Like how he stands out from the background. Nice and green against the red/brown.</td>', 'What a cute little bugger! Like how he stands out from the background. Nice and green against the red/brown.', '2006-09-06 15:05:37.000000', NULL, 1),
(2805863, 387461, 44611, '<td valign="top">How you''ve managed to make a wrecked pontoon look so romantic and magical I really don''t know but I do know it demonstrates enormous talent!  I shall be checking back and hope you give us more information on how you captured and processed this incredible image.</td>', 'How you''ve managed to make a wrecked pontoon look so romantic and magical I really don''t know but I do know it demonstrates enormous talent!  I shall be checking back and hope you give us more information on how you captured and processed this incredible image.', '2006-09-06 15:06:18.000000', NULL, 1),
(2805868, 379749, 41794, '<td valign="top">Lovely cannon shot. Nice balance of colors and good crisp focus. Makes me want to go back again!</td>', 'Lovely cannon shot. Nice balance of colors and good crisp focus. Makes me want to go back again!', '2006-09-06 15:07:02.000000', NULL, 1),
(2805871, 379842, 44611, '<td valign="top">Lovely shot of water and good detail on the foreground stones.  I like the colours a lot.</td>', 'Lovely shot of water and good detail on the foreground stones.  I like the colours a lot.', '2006-09-06 15:07:22.000000', NULL, 1),
(2805874, 386028, 41794, '<td valign="top">Wonderful color saturation! Love the green in the trees and the grass against that beautiful sky.</td>', 'Wonderful color saturation! Love the green in the trees and the grass against that beautiful sky.', '2006-09-06 15:07:41.000000', NULL, 1),
(2805879, 388543, 44611, '<td valign="top">Well caught!  Perhaps the exposure could be a bit clearer, but a good shot of the moment.</td>', 'Well caught!  Perhaps the exposure could be a bit clearer, but a good shot of the moment.', '2006-09-06 15:08:17.000000', NULL, 1),
(2805880, 388541, 41794, '<td valign="top">How precious!</td>', 'How precious!', '2006-09-06 15:08:17.000000', NULL, 1),
