(2808755, 384645, 47906, '<td valign="top">Great shot, my kind of heaven</td>', 'Great shot, my kind of heaven', '2006-09-07 02:23:44.000000', NULL, 1),
(2808757, 386103, 60862, '<td valign="top">Would grab me more with sharper focus and more contrast.  I like the long, tall crop, though.</td>', 'Would grab me more with sharper focus and more contrast.  I like the long, tall crop, though.', '2006-09-07 02:23:52.000000', NULL, 1),
(2808758, 388170, 60862, '<td valign="top">Cool treatment.  His eyes are glowing to the point of looking supernatural.</td>', 'Cool treatment.  His eyes are glowing to the point of looking supernatural.', '2006-09-07 02:24:24.000000', NULL, 1),
