(2811244, 388713, 16197, '<td valign="top">Very vivid and alive capture.  Just not quite sharp enough.  I would like to see more distinction between the flower and th background.</td>', 'Very vivid and alive capture.  Just not quite sharp enough.  I would like to see more distinction between the flower and th background.', '2006-09-07 17:14:29.000000', NULL, 1),
(2811245, 388951, 50641, '<td valign="top">Interesting.</td>', 'Interesting.', '2006-09-07 17:14:40.000000', NULL, 1),
